22	// zero-based record or array position and says the bytes are invalid.
23	func TestUnmarshalPlanRejectsCorruptNameBytes(t *testing.T) {
24		cases := map[string]struct {
25			data     string
26			field    string
27			location string
28		}{
29			"change name": {
30				`{"changes":[{"name":"source` + "\xff" + `","upstreams":[]}]}`,
31				`"name"`, `index 0 of "changes"`,
32			},
33			"change name in second record": {
34				`{"changes":[{"name":"A","upstreams":[]},{"name":"b` + "\xfe" + `","upstreams":[]}]}`,
35				`"name"`, `index 1 of "changes"`,
36			},
37			"upstream entry": {
38				`{"changes":[{"name":"A","upstreams":["ok","g` + "\xfe" + `"]}]}`,
39				`"upstreams"`, `index 1`,
40			},
41			"upstream entry in second record": {
42				`{"changes":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A","x` + "\xff" + `"]}]}`,
43				`"upstreams"`, `index 1`,
44			},
45			"removals entry": {
46				`{"removals":["a","b","c` + "\xc3" + `"]}`,
47				`"removals"`, `index 2`,
48			},
49			"removals entry naming a dataset that does not exist": {
50				// Even a name that would only delete a nonexistent dataset is
51				// refused: the reader must not treat the corruption as a no-op.
52				`{"removals":["ghost` + "\xff" + `"]}`,
53				`"removals"`, `index 0`,
54			},
55			"case-folded known field is still checked": {
56				`{"CHANGES":[{"NAME":"a` + "\xff" + `"}]}`,
57				`"name"`, `index 0 of "changes"`,
58			},
59			"escaped key spelling is still checked": {
60				`{"changes":[{"na\u006de":"a` + "\xff" + `"}]}`,
61				`"name"`, `index 0 of "changes"`,
62			},
63		}
64		for name, tc := range cases {
65			t.Run(name, func(t *testing.T) {
66				_, err := UnmarshalPlan([]byte(tc.data))
67				if !errors.Is(err, ErrInvalidArgument) {
68					t.Fatalf("err = %v, want ErrInvalidArgument", err)
69				}
70				msg := err.Error()
71				if !strings.Contains(msg, "invalid UTF-8 bytes") {
72					t.Errorf("err = %q, want it to say the bytes are invalid UTF-8", msg)
73				}
74				if strings.Contains(msg, "surrogate") {
75					t.Errorf("err = %q, byte corruption must not be reported as a surrogate problem", msg)
76				}
77				if !strings.Contains(msg, tc.field) {
78					t.Errorf("err = %q, want it to name field %s", msg, tc.field)
79				}
80				if !strings.Contains(msg, tc.location) {
81					t.Errorf("err = %q, want it to locate %s", msg, tc.location)
82				}
83				if strings.Contains(msg, "�") {
84					t.Errorf("err = %q, must not contain the replacement character", msg)
85				}
86			})
87		}
88	}
