18			Removals: []string{"A"},
19		}
20		report, err := PreviewBatch(graph, plan)
21		if err != nil {
22			t.Fatalf("PreviewBatch unexpected error: %v", err)
23		}
24		wantRemoved := []string{"A"}
25		if !reflect.DeepEqual(report.RemovedDatasets, wantRemoved) {
26			t.Errorf("RemovedDatasets = %v, want %v", report.RemovedDatasets, wantRemoved)
