1	package chainledger
2	
3	import (
4		"encoding/json"
5		"errors"
6		"reflect"
7		"strings"
8		"testing"
9		"unicode/utf8"
10	)
11	
12	// These tests pin the rule that an in-memory graph whose names are not valid
13	// UTF-8 can never be exported or snapshotted: encoding/json would silently
14	// rewrite each invalid byte into U+FFFD, so two different names could collapse
15	// into one and a re-read graph would not be a copy of the original. Both
16	// exporters must refuse the whole graph instead.
17	
18	// invalidUTF8GraphCase places one invalid name in each location that reaches an
19	// exporter: a root dataset key, a derived dataset key, and a direct upstream
20	// reference (both registered and missing from the node set).
21	var invalidUTF8GraphCases = map[string]func() map[string]*Lineage{
22		"invalid root dataset name": func() map[string]*Lineage {
23			return map[string]*Lineage{
24				"root\xff": {Dataset: "root\xff"},
25				"derived":  {Dataset: "derived", Parents: []string{"root\xff"}},
26			}
27		},
28		"invalid derived dataset name": func() map[string]*Lineage {
29			return map[string]*Lineage{
30				"root":    {Dataset: "root"},
31				"der\xfe": {Dataset: "der\xfe", Parents: []string{"root"}},
32			}
33		},
34		"invalid direct upstream reference, registered": func() map[string]*Lineage {
35			// The referenced upstream is itself a node, so its key and the
36			// referrer's Parents entry both carry the same invalid bytes.
37			return map[string]*Lineage{
38				"up\xff": {Dataset: "up\xff"},
39				"down":   {Dataset: "down", Parents: []string{"up\xff"}},
40			}
41		},
42		"invalid direct upstream reference, not registered": func() map[string]*Lineage {
43			// An unregistered upstream is normally ErrNotFound, but an unusable
44			// name must surface as ErrInvalidArgument regardless.
45			return map[string]*Lineage{
46				"down": {Dataset: "down", Parents: []string{"ghost\xff"}},
47			}
48		},
49	}
50	
51	func TestMarshalGraphFileRejectsInvalidUTF8(t *testing.T) {
52		for name, build := range invalidUTF8GraphCases {
53			t.Run(name, func(t *testing.T) {
54				graph := build()
55				out, err := MarshalGraphFile(graph)
56				if err == nil {
57					t.Fatalf("MarshalGraphFile accepted a graph with invalid UTF-8 and returned %s", out)
58				}
59				if !errors.Is(err, ErrInvalidArgument) {
60					t.Fatalf("err = %v, want errors.Is ErrInvalidArgument", err)
61				}
62				if out != nil {
63					t.Fatalf("export returned %d bytes despite the error: %s", len(out), out)
64				}
65				// The error must carry the original bytes, not their replacement:
66				// %q renders invalid bytes as \x escapes and must not print U+FFFD.
67				msg := err.Error()
68				if strings.Contains(msg, "�") {
69					t.Fatalf("error shows the replacement character instead of the original bytes: %q", msg)
70				}
71				if !strings.Contains(msg, `\x`) {
72					t.Fatalf("error does not quote the original offending bytes: %q", msg)
73				}
74			})
75		}
76	
77		t.Run("single invalid name with no possible collision", func(t *testing.T) {
78			// Even one root alone, with no other name to collide with, must fail.
79			graph := map[string]*Lineage{"only\xff": {Dataset: "only\xff"}}
80			if out, err := MarshalGraphFile(graph); err == nil {
81				t.Fatalf("single-node graph with invalid UTF-8 was exported as %s", out)
82			}
83		})
84	}
85	
86	func TestBuildSnapshotRejectsInvalidUTF8(t *testing.T) {
87		for name, build := range invalidUTF8GraphCases {
88			t.Run(name, func(t *testing.T) {
89				graph := build()
90				snap, err := BuildSnapshot(graph)
91				if err == nil {
92					t.Fatalf("BuildSnapshot accepted a graph with invalid UTF-8: %#v", snap)
93				}
94				if !errors.Is(err, ErrInvalidArgument) {
95					t.Fatalf("err = %v, want errors.Is ErrInvalidArgument", err)
96				}
97				if snap != nil {
98					t.Fatalf("BuildSnapshot returned snapshot %#v despite the error", snap)
99				}
100				msg := err.Error()
101				if strings.Contains(msg, "�") || !strings.Contains(msg, `\x`) {
102					t.Fatalf("error must name the original bytes, got %q", msg)
103				}
104			})
105		}
106	
107		t.Run("single invalid name with no possible collision", func(t *testing.T) {
108			graph := map[string]*Lineage{"only\xfe": {Dataset: "only\xfe"}}
109			if snap, err := BuildSnapshot(graph); err == nil {
110				t.Fatalf("single-node graph with invalid UTF-8 produced snapshot %#v", snap)
111			}
112		})
113	}
114	
115	// Two names that differ only in an invalid byte (0xFF vs 0xFE) would both be
116	// serialized as the same "prefix�" node; their rejection messages must still
117	// tell the two original names apart.
118	func TestInvalidUTF8NamesRemainDistinguishableInErrors(t *testing.T) {
119		// Document why the gate exists: without it the JSON encoder does exactly
120		// the silent collision the task describes: both names marshal identically
121		// and decode back to the same replacement-character name.
122		a, _ := json.Marshal("p\xff")
123		b, _ := json.Marshal("p\xfe")
124		if string(a) != string(b) {
125			t.Fatalf("test premise changed: json.Marshal gives %s and %s", a, b)
126		}
127		var decoded string
128		if err := json.Unmarshal(a, &decoded); err != nil {
129			t.Fatalf("decoding marshaled name: %v", err)
130		}
131		if decoded != "p"+string(utf8.RuneError) {
132			t.Fatalf("marshaled name decodes to %q, not the replacement name", decoded)
133		}
134	
135		graphFF := map[string]*Lineage{"p\xff": {Dataset: "p\xff"}}
136		graphFE := map[string]*Lineage{"p\xfe": {Dataset: "p\xfe"}}
137		_, errFF := MarshalGraphFile(graphFF)
138		_, errFE := MarshalGraphFile(graphFE)
139		if errFF == nil || errFE == nil {
140			t.Fatalf("expected both graphs rejected, got %v, %v", errFF, errFE)
141		}
142		if errFF.Error() == errFE.Error() {
143			t.Fatalf("0xFF and 0xFE produced the same error message: %q", errFF)
144		}
145		if !strings.Contains(errFF.Error(), `\xff`) || !strings.Contains(errFE.Error(), `\xfe`) {
146			t.Fatalf("errors do not show the distinct original bytes:\n%q\n%q", errFF, errFE)
147		}
148	}
149	
150	// The reported name must be stable no matter how the map chooses to iterate.
151	func TestInvalidUTF8ReportedNameIsDeterministic(t *testing.T) {
152		graph := map[string]*Lineage{
153			"z\xff": {Dataset: "z\xff"},
154			"a\xfe": {Dataset: "a\xfe"},
155		}
156		first, err := MarshalGraphFile(graph)
157		if err == nil {
158			t.Fatalf("expected rejection, got %s", first)
159		}
160		want := err.Error()
161		for i := 0; i < 20; i++ {
162			if _, err := MarshalGraphFile(graph); err.Error() != want {
163				t.Fatalf("error message varied across calls:\n%q\n%q", want, err)
164			}
165			if _, err := BuildSnapshot(graph); err.Error() != want {
166				t.Fatalf("BuildSnapshot reports a different name than MarshalGraphFile:\n%q\n%q", want, err)
167			}
168		}
169	}
170	
171	// nodeCopy is a value snapshot of one lineage node for deep comparisons.
172	type nodeCopy struct {
173		Dataset  string
174		Parents  []string
175		Children []string
176	}
177	
178	func snapshotGraph(graph map[string]*Lineage) map[string]nodeCopy {
179		cp := make(map[string]nodeCopy, len(graph))
180		for name, entry := range graph {
181			if entry == nil {
182				cp[name] = nodeCopy{}
183				continue
184			}
185			cp[name] = nodeCopy{
186				Dataset:  entry.Dataset,
187				Parents:  append([]string(nil), entry.Parents...),
188				Children: append([]string(nil), entry.Children...),
189			}
190		}
191		return cp
192	}
193	
194	// Rejecting an export must not normalize, reorder, truncate, or otherwise
195	// touch the caller's graph — including deliberately unsorted lists.
196	func TestRejectedExportLeavesGraphUntouched(t *testing.T) {
197		graph := map[string]*Lineage{
198			"root\xff": {Dataset: "root\xff", Children: []string{"later", "earlier"}},
199			"down":     {Dataset: "down", Parents: []string{"mid\xff", "first"}, Children: []string{}},
200		}
201		before := snapshotGraph(graph)
202	
203		if out, err := MarshalGraphFile(graph); err == nil {
204			t.Fatalf("expected rejection, got %s", out)
205		}
206		if snap, err := BuildSnapshot(graph); err == nil {
207			t.Fatalf("expected rejection, got %#v", snap)
208		}
209	
210		if after := snapshotGraph(graph); !reflect.DeepEqual(after, before) {
211			t.Fatalf("graph changed during a rejected export:\nbefore %#v\nafter  %#v", before, after)
212		}
213	}
214	
215	// A legal graph is also only read during export.
216	func TestSuccessfulExportLeavesGraphUntouched(t *testing.T) {
217		graph := make(map[string]*Lineage)
218		if err := Register(graph, Dataset{Name: "root"}, nil); err != nil {
219			t.Fatalf("Register root: %v", err)
220		}
221		if err := Register(graph, Dataset{Name: "derived"}, []string{"root"}); err != nil {
222			t.Fatalf("Register derived: %v", err)
223		}
224		before := snapshotGraph(graph)
225		if _, err := MarshalGraphFile(graph); err != nil {
226			t.Fatalf("MarshalGraphFile: %v", err)
227		}
228		if _, err := BuildSnapshot(graph); err != nil {
229			t.Fatalf("BuildSnapshot: %v", err)
230		}
231		if after := snapshotGraph(graph); !reflect.DeepEqual(after, before) {
232			t.Fatalf("legal graph changed during export:\nbefore %#v\nafter  %#v", before, after)
233		}
234	}
235	
236	// Register remains an open ingress for any Go string, including invalid UTF-8;
237	// validation happens at the export boundary.
238	func TestRegisterAcceptsInvalidUTF8ButExportRejects(t *testing.T) {
239		graph := make(map[string]*Lineage)
240		if err := Register(graph, Dataset{Name: "root\xff"}, nil); err != nil {
241			t.Fatalf("Register must accept the bytes the Go API was given, got %v", err)
242		}
243		if err := Register(graph, Dataset{Name: "derived"}, []string{"root\xff"}); err != nil {
244			t.Fatalf("Register child of non-UTF-8 root: %v", err)
245		}
246		if _, err := MarshalGraphFile(graph); !errors.Is(err, ErrInvalidArgument) {
247			t.Fatalf("MarshalGraphFile err = %v, want ErrInvalidArgument", err)
248		}
249		if _, err := BuildSnapshot(graph); !errors.Is(err, ErrInvalidArgument) {
250			t.Fatalf("BuildSnapshot err = %v, want ErrInvalidArgument", err)
251		}
252	}
253	
254	// Names that ARE valid UTF-8 — including a genuine replacement character that
255	// looks like the rejected output, CJK, emoji, combining-mark variants, casing,
256	// and surrounding spaces — are accepted verbatim and survive a full round trip
257	// with no Unicode normalization.
258	func TestValidUnicodeNamesExportAndRoundTrip(t *testing.T) {
259		if !utf8.ValidString("�") {
260			t.Fatal("a literal replacement character must be valid UTF-8")
261		}
262		// "é" is e + combining acute accent; "é" is the precomposed
263		// "é". They display alike but are different names and must stay so.
264		names := []string{"�", "数据集", "ledger😀", "é", "é", "Ledger", "ledger", " spaced "}
265		graph := make(map[string]*Lineage, len(names)+1)
266		if err := Register(graph, Dataset{Name: names[0]}, nil); err != nil {
267			t.Fatalf("Register: %v", err)
268		}
269		for _, name := range names[1:] {
270			if err := Register(graph, Dataset{Name: name}, []string{names[0]}); err != nil {
271				t.Fatalf("Register %q: %v", name, err)
272			}
273		}
274	
275		// Graph export round trip keeps every name and the direct relations.
276		data, err := MarshalGraphFile(graph)
277		if err != nil {
278			t.Fatalf("MarshalGraphFile rejected valid Unicode: %v", err)
279		}
280		reRead, err := UnmarshalGraphFile(data)
281		if err != nil {
282			t.Fatalf("re-reading the exported graph: %v", err)
283		}
284		wantAdj := map[string][]string{}
285		for _, name := range names {
286			if name == names[0] {
287				// A root round-trips with no parents (nil slice); only the
288				// absence of an upstream list matters for semantics.
289				wantAdj[name] = nil
290			} else {
291				wantAdj[name] = []string{names[0]}
292			}
293		}
294		gotAdj := map[string][]string{}
295		for name, entry := range reRead {
296			gotAdj[name] = entry.Parents
297		}
298		if !reflect.DeepEqual(gotAdj, wantAdj) {
299			t.Fatalf("round trip changed names/relations:\n got %#v\nwant %#v", gotAdj, wantAdj)
300		}
301		if !utf8.ValidString("é") || graph["é"].Parents[0] != "�" {
302			t.Fatal("combining-form name must be kept byte-for-byte")
303		}
304	
305		// Snapshot round trip yields the same content identifier and graph.
306		snap, err := BuildSnapshot(graph)
307		if err != nil {
308			t.Fatalf("BuildSnapshot rejected valid Unicode: %v", err)
309		}
310		snapBytes, err := MarshalSnapshot(snap)
311		if err != nil {
312			t.Fatalf("MarshalSnapshot: %v", err)
313		}
314		parsed, err := ParseSnapshot(snapBytes)
315		if err != nil {
316			t.Fatalf("ParseSnapshot: %v", err)
317		}
318		if parsed.ContentID != snap.ContentID {
319			t.Fatalf("content id changed across round trip: %q vs %q", parsed.ContentID, snap.ContentID)
320		}
321		if !reflect.DeepEqual(parsed.Graph, snap.Graph) {
322			t.Fatalf("snapshot graph changed across round trip")
323		}
324	}
325	
326	// An empty graph stays legal at the export boundary after the new gate.
327	func TestEmptyGraphStillExportsAndSnapshots(t *testing.T) {
328		empty := map[string]*Lineage{}
329		data, err := MarshalGraphFile(empty)
330		if err != nil {
331			t.Fatalf("MarshalGraphFile(empty): %v", err)
332		}
333		if _, err := UnmarshalGraphFile(data); err != nil {
334			t.Fatalf("re-reading exported empty graph: %v", err)
335		}
336		snap, err := BuildSnapshot(empty)
337		if err != nil {
338			t.Fatalf("BuildSnapshot(empty): %v", err)
339		}
340		if snap.FormatVersion != SnapshotFormatVersion || snap.ContentID == "" {
341			t.Fatalf("empty graph snapshot malformed: %#v", snap)
342		}
343	}
