// assertCorruptNameError checks the shared shape of every corrupt-name
// rejection: ErrInvalidArgument, the right field and position, the raw bytes
// quoted as \x escapes, and neither a U+FFFD substitution nor a not-found
// classification.
func assertCorruptNameError(t *testing.T, err error, field string, location []string) {
	t.Helper()
